quests[33057] = { id = 33057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Rotbelcher" }
quests[33059] = { id = 33059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal von Karabor", description = "Stränge der Zukunft verwirren sich ineinander, schließen sich zusammen und lösen sich wieder auf. Sie bilden ein Geflecht, dessen Form und Farbe sich von einem Moment zum anderen verändert.\n\nIch muss Klarheit finden. Ich muss mich auf den EINEN Strang konzentrieren, der Wirklichkeit werden wird.\n\nWenn Ihr bereit seid, meine Vision zu teilen, trinkt das Elixier.\n\nSobald die Vision beginnt, seid auf der Hut. Die Ereignisse, die sich in ihr entfalten, sind genauso tödlich wie alles, was wir in dieser Realität erleben.", sourceObjective = "Trinkt das Elixier der Klarheit und werdet Zeuge des Schicksals von Karabor.", completion = "Ich habe genug gesehen. Ner'zhul muss aufgehalten werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33061] = { id = 33061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Amaukwa" }
quests[33062] = { id = 33062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seine Aufmerksamkeit erregen", description = "Für die anstehende Aufgabe brauche ich jemanden, dem ich trauen kann. Ihr gehört zu diesen wenigen.\n\nDie Wälder und das Orcdorf Gul'var sind vor meiner Wahrsagermagie geschützt. Wir müssen diesen Schleier durchdringen, und ich weiß vielleicht, wie wir das schaffen.\n\nEs gibt eine teuflische Präsenz in den Wäldern. Ein dämonischer Beobachter liegt dort in einer Höhle verborgen, aus der er seinen allsehenden Blick schweifen lässt.\n\nIch möchte Euch und die Wächterin bitten, ihn zu fangen.", sourceObjective = "Fangt das allsehende Auge.", completion = "Sobald wir genug gesegnetes Wasser aus dem Mondbrunnen der Priesterin haben, werden wir den Willen des Dämons brechen und mit seiner Hilfe nach Gul'var schauen.\n\nAuf diese Weise werden sie nicht merken, dass wir es sind, die auf sie blicken.\n\nDoch zuerst müssen wir die Magie schwächen, die Gul'var verhüllt.", sourceObjectiveStatus = "unverified-source-field" }
quests[33064] = { id = 33064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Schattenmondkultistenritual" }
quests[33065] = { id = 33065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mooncrush" }
quests[33066] = { id = 33066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelensplitter der Beschwörung", description = "Es ist gut zu wissen, was Teron'gor und Cho'gall vorhaben. Aber es ist noch wichtiger, dass wir Gul'dan aufhalten.\n\nEinige seiner Schüler können geringere Dämonen beschwören. Dazu müssen diese niederen Hexenmeister einen Seelensplitter benutzen. Dieser widerliche Kristall stellt eine Verbindung zum Wirbelnden Nether her und zieht einen Dämon gegen seinen Willen hindurch.\n\nGul'dan ist nicht weniger Dämon als Orc. Wenn wir ein paar der größeren Splitter sammeln, können wir daraus vielleicht etwas machen, womit wir ihn fangen können.", sourceObjective = "Bringt Kurgoths Splitter, Grogals Splitter und Hagras Splitter in Euren Besitz.", progress = "Habt Ihr die Splitter, {name}?", completion = "Jetzt müssen wir sie nur noch zu etwas zusammensetzen, das stark genug ist, um Gul'dan zu fesseln.\n\nZum Glück können wir das genau hier tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[33069] = { id = 33069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSEME" }
quests[33070] = { id = 33070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Denkt denn niemand an die Kinder?!", description = "Als die Schattenmondorcs den Baumhain angriffen, brach überall Panik aus.\n\nViele von uns konnten entkommen, aber es werden immer noch drei Kinder vermisst.\n\nIch glaube, sie befinden sich immer noch im Dorf.\n\nBitte rettet sie!", sourceObjective = "Rettet Rastaak, Ariaana und Hakaam.", completion = "Ich bin sehr froh darüber, dass die Kinder in Sicherheit sind. Sie werden Eure Heldentat ihr ganzes Leben lang nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33071] = { id = 33071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of War" }
quests[33072] = { id = 33072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Zwielicht", description = "Die Sicherheit meines Volkes steht an oberster Stelle.\n\nWahrscheinlich hat Ner'zhul die Gefangenen nach Shaz'gul gebracht, seiner Festung im Südwesten.\n\nIch möchte körperliche Gewalt vermeiden, aber er lässt mir vielleicht keine andere Wahl.\n\nSucht mich auf der Zwielichtflur auf, {name}. Dann werden wir unser Bestes geben, um die Gefangenen zu retten.", sourceObjective = "Sprecht mit Prophet Velen auf der Zwielichtflur.", completion = "Danke, dass Ihr gekommen seid, {name}. Es gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[33073] = { id = 33073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Uralte Salzschnappschildkröte" }
quests[33075] = { id = 33075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Heldenempfang", description = "Prophet Velen hat mich gebeten, Euch im Schattenmondtal herumzuführen.\n\nZunächst gehen wir nach Embaari, wo meine Schwester Samaara auf uns wartet. Ich habe sie nicht mehr gesehen, seit die Eiserne Horde mich nach Tanaan gebracht hat.\n\nDas Dorf ist nur eins von vielen Handelsdörfern zwischen dem Tempel von Karabor und Shattrath.\n\nFolgt der Straße nach Osten und Ihr gelangt direkt nach Embaari. Ich werde Euch begleiten.", sourceObjective = "Sprecht mit Samaara in Embaari.", completion = "Ich danke Euch, Fremder! Der Prophet sprach davon, dass neue Verbündete an unseren Gestaden angekommen sind.\n\nWie ich höre, ist meine Schwester dank Euch in Sicherheit.\n\nIch stehe tief in Eurer Schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[33076] = { id = 33076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Elixier der Klarheit", description = "Ich erhasche tausend Blicke in die Zukunft, die zu einem wirren Durcheinander verschwimmen.\n\nEs ist möglich, meine Energien so zu fokussieren, dass die wahre Eventualität sichtbar wird – die Zukunft, die höchstwahrscheinlich eintreffen wird.\n\nIch benötige einen Orakelstein. um meine Kraft zu fokussieren und ein spezielles Elixier, um meinen Geist zur Ruhe zu bringen.\n\nFür die Herstellung des Elixiers brauche ich folgende Zutaten: Flügelstaub von den Sumpfleuchtern entlang des Flusses, frische Herzen von einer monströs großen Hydra und eine seltene Sternenlilie.\n\nWir treffen uns am Mondweidengipfel, wenn die Aufgabe erfüllt ist.", sourceObjective = "Sammelt 6 Sumpfleuchterstaub, 3 geschwollene Herzen und 1 Sternenblume.", progress = "Ja?", completion = "Mein Vertrauen in Euch ist wirklich berechtigt, junger {class}.\n\nDiese Aufgabe wäre für viele meiner Schüler beschwerlich gewesen, aber Ihr habt sie mit Leichtigkeit gemeistert.", sourceObjectiveStatus = "unverified-source-field" }
quests[33077] = { id = 33077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großmutters Hausmittel", description = "Sieh einer an, was für <einen kräftigen jungen Burschen/eine kräftige junge Dame> haben wir denn hier? So voller Energie und Leidenschaft!\n\nGenießt es – wenn Ihr einmal mein Alter erreicht, dann werdet Ihr Euch vor Schmerzen kaum mehr bewegen können.\n\nGlücklicherweise habe ich ein Rezept für eine Salbe, die meine Leiden lindern sollte. Ich benötige lediglich das Bauchsekret der Bauchunken, die sich im Sumpf finden lassen.\n\nWollt Ihr nicht ein Schatz sein und einer alten Dame helfen?", sourceObjective = "Sammelt 6 Fläschchen Krötensaft zusammen.", progress = "Ich kann Euch sagen, ich bin auch keine sechzehn mehr, mein Lieber.", completion = "Oh, ich danke Euch, mein Lieber! Vielen, vielen Dank.\n\nDie Nächte im Sumpf sind wirklich bitterkalt. Es ist eine große Erleichterung für mich alte Dame, wenn die Knochen nicht mehr so schmerzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33078] = { id = 33078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Dunkel, das uns blendet", description = "Nach Jahren der Forschung gibt es immer noch so viel, was ich über den Schattenmondklan nicht verstehe.\n\nIm Südwesten gibt es Steinmonumente, die die Geschichte der Orcs beschreiben.\n\nIch kann nicht nahe genug an die Steine herankommen, um sie zu untersuchen, aber Ihr vielleicht.\n\nWenn Ihr die Wörter auf diesen Steinen mit Kreide abpausen könntet, würde ich Euch reich belohnen.", sourceObjective = "Fertigt mit Kreide Abpausbilder von den Stammessteinen im Norden, im Osten, im Westen und im Süden der Flüsternden Felder an.", progress = "Was habt Ihr herausgefunden?", completion = "Meine Güte, ich verstehe! Ich verstehe es! Diese Inschriften werden mir einen tiefen Einblick in die Kultur des Schattenmondklans gewähren.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33079] = { id = 33079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demons Among Us - Alliance" }
quests[33080] = { id = 33080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdeckte Operation", description = "Yrel sucht zusammen mit meinen Waldläufern nach den Gefangenen in Schattenmond.\n\nIhre Arbeit ist extrem gefährlich, Ihr müsst also für mich auf eine Notfallmission gehen.\n\nSylene hat einen Illusionszauber gemeistert, mit dessen Hilfe Ihr Euch problemlos unter die Shaz'gul mischen könnt. Sprecht mit ihr, um Euch zu tarnen.\n\nDann platziert Sprengsätze im Rüstmeisterquartier, im Hauptgebäude und am Ritualaltar.\n\nFalls etwas schief geht, zündet sie zur Ablenkung.", sourceObjective = "Sprecht mit Sylene auf der Zwielichtflur, um eine Orcillusion zu erhalten, und platziert dann Sprengstoff an Schlüsselpositionen in Shaz'gul.\n\nFalls Ihr Eure Verkleidung verliert, benutzt Sylenes Illusionsamulett, um erneut die Gestalt eines Orcs anzunehmen.", completion = "Ihr habt es geschafft, {name}. Ich bin froh, Euch wiederzusehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33081] = { id = 33081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus Shaz'gul", description = "Ich habe versagt, {name}...\n\nMein Trupp ist von einer Patrouille erwischt worden. Wir haben tapfer gekämpft, aber sie konnten Alarm schlagen. Die Rangari bestanden darauf, dass ich mich verstecke, bevor sie sich dem Feind ergaben.\n\nSie standen unter MEINEM Befehl und sie haben ihre Leben geopfert... aber wofür? Ich... ich bin mir nicht sicher, was ich jetzt tun soll, {name}.\n\nWir müssen hier raus, aber wie?", sourceObjective = "Helft Yrel bei ihrer Flucht aus Shaz'gul.", completion = "Ohne Euch hätte ich das niemals geschafft, {name}. Eure Worte haben etwas in mir ausgelöst, das ich noch nie zuvor gespürt habe.\n\nNennt es, wie Ihr wollt – Entschlossenheit, Überzeugung, Glaube. Ich werde Euch das nicht vergessen, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33082] = { id = 33082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Andenken an die Ahnen", description = "Ich denke, Ihr solltet den Preis der Leben kennen, die Ihr nehmt.\n\nBevor ich Euch also helfe, Ner'zhul zu finden, müsst Ihr verstehen, warum er der Eisernen Horde beigetreten ist.\n\nIn einer Höhle unter diesem Dorf liegt ein Artefakt, das wir das Totem der Ahnen nennen. Darauf sind die Namen aller Schattenmondklanmitglieder seit seiner Gründung eingeschnitzt.\n\nDer Eingang zur Höhle ist direkt im Süden. Ich werde dort zu Euch stoßen.", sourceObjective = "Findet das Ahnentotem in der Höhle unter der Anhöhe der Exilanten.", completion = "Wir werden neue Traditionen finden. Mein Volk wird sich... erneuern.", sourceObjectiveStatus = "unverified-source-field" }
quests[33083] = { id = 33083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In der Offensive", description = "Wir können diese Tore nicht durchschreiten, doch Ihr könnt es, {class}.\n\nEure Mission ist ausgesprochen wichtig und der Schattenmondklan wird Euch sofort töten, wenn Ihr gefunden werdet. Zögert nicht, ihnen denselben Gefallen zu erweisen.", sourceObjective = "Tötet 15 Dunkelzauberer des Schattenmondklans oder Leerenklauen des Schattenmondklans.", completion = "Der Schattenmondklan ist kein einfacher Gegner. Eure kämpferischen Fähigkeiten sind einfach unvergleichlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[33084] = { id = 33084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jede Menge Fleisch", description = "Kommandant! Ich hätte nicht erwartet, Euch hier draußen über den Weg zu laufen.\n\nDie Garnison hat ganz schön viele hungrige Mäuler zu stopfen und jeden Tag werden es mehr.\n\nWir werden jede Menge Fleisch brauchen, um alle bei Laune zu halten.\n\nWürde es Euch was ausmachen, uns zu helfen? Mit <einem zusätzlichen Helfer/einer zusätzlichen Helferin> sind wir schneller fertig.", sourceObjective = "Sammelt 1000 rohe Elekksteaks.", progress = "Habt Ihr gesehen, wie groß die Biester sind?", completion = "Fantastisch, einfach fantastisch! So viel Fleisch habe ich in meinem Leben noch nicht gesehen.\n\nMacht die Wagen bereit. Heute Abend lassen wir es uns schmecken!", sourceObjectiveStatus = "unverified-source-field" }
quests[33086] = { id = 33086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsquest: Die Wurzeln der Dunkelheit - Stein 1" }
quests[33087] = { id = 33087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft mich in der Taverne", description = "Ihr wollt Euren neuen Umhang doch bestimmt einmal ausprobieren, oder? Lasst uns sehen, was er kann.\n\nTrefft Euch mit mir in der Taverne! Ich bin auf eine neue Entwicklung aufmerksam geworden, die wir nicht ungenutzt lassen sollten.", sourceObjective = "Trefft Furorion oben in der Taverne im Nebel an der Verhüllten Treppe.", sourceObjectiveStatus = "unverified-source-field" }
quests[33088] = { id = 33088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zeitlose Entdeckung", description = "Pandaria. Gerade als ich dachte, dass all seine Mysterien offengelegt wurden, entdecke ich etwas Neues: die Zeitlose Insel!\n\nAuch sie lag im Nebel verborgen und offenbart sich scheinbar willkürlich der Außenwelt – genauso schnell, wie sie wieder verschwindet. Ich habe gehört, dass die Zeit dort keine Bedeutung hat und die Sonne weder auf- noch untergeht.\n\nDiese Anomalie können wir zu unseren Gunsten nutzen, {name}! Falls ich Euren Umhang zeitversiegeln könnte, dann wäre die Macht, die er beinhalten könnte, immens!\n\nUnsere Mission liegt vor uns. Trefft mich auf der Zeitlosen Insel südöstlich des Jadewalds!", sourceObjective = "Reist zur Zeitlosen Insel südöstlich des Jadewalds und sprecht mit Furorion.", sourceObjectiveStatus = "unverified-source-field" }
quests[33089] = { id = 33089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Proving Grounds - Damage Bronze" }
