quests[33097] = { id = 33097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Proving Grounds - Healer Gold" }
quests[33098] = { id = 33098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Zeitlosen Insel", description = "Es gibt eine Währung, die nur auf dieser Insel geprägt wird – \"Zeitlose Münzen\". Diese Münzen sind immun gegen die örtlichen Zeitverzerrungen... und ich wüsste gerne wieso.\n\nSammelt ein paar von ihnen für mich! Erforscht die Dschungel dieses vergessenen Paradieses. Vernichtet die mysteriösen Feinde, die sich an diesem zeitlosen Ort herumtreiben, entdeckt verborgene Schatztruhen und erkundet längst vergessene Verstecke. Egal, wie Ihr es anstellt – ich werde auf Euch warten!", sourceObjective = "Sammelt 5000 zeitlose Münzen von Kreaturen und Ereignissen auf der Zeitlosen Insel.", sourceObjectiveStatus = "unverified-source-field" }
quests[33100] = { id = 33100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weg des Kaisers", description = "Kürzlich haben Euch die Himmlischen Erhabenen einer Prüfung unterzogen – und Ihr habt sie gemeistert.\n\nAber könnt Ihr die Erhabenen auch im Kampf bezwingen? Sie stellen den Mut aller Helden Pandarias auf die Probe.\n\nDiese Herausforderung ist nur dann zu bewältigen, wenn Ihr dem Rat des letzten Kaisers der Pandaren folgt und sie mit unbeirrter innerer Stärke angeht. Außerdem werdet Ihr eine kleine Armee benötigen, also sucht Euch eine Gruppe Mitstreiter, denen Ihr vertraut.\n\nBezwingt die vier Erhabenen hier im Hof der Erhabenen, dann ist unsere Reise beinahe an ihrem Ende angekommen...", sourceObjective = "Bezwingt Yu'lon, Chi-Ji, Xuen und Niuzao, die vier Himmlischen Erhabenen Pandarias.", sourceObjectiveStatus = "unverified-source-field" }
quests[33104] = { id = 33104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Legende Pandarias", description = "<Mein Freund/Meine Gute>, ich habe an diesem zeitlosen Ort viel gelernt. Die Weisheit der Erhabenen sowie die seltsamen Mächte der zeitlosen Artefakte haben mich gelehrt, wie ich mit meiner eigenen bedeutenden Macht Euren Umhang gefahrlos verbessern kann.\n\nFür meine letzten Zaubersprüche ist ein heiliger Ort vonnöten. Schnell! Sucht mich im Tal der Ewigen Blüten auf, im Heim des Wissens oberhalb des Mogu'shanpalasts.\n\nHeute beginnt Eure Legende!", sourceObjective = "Trefft Furorion im Heim des Wissens im Tal der Ewigen Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33105] = { id = 33105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urteil des Schwarzen Prinzen", description = "Und jetzt zum letzten Schritt meines Plans. Es ist an der Zeit, dass Ihr Euren bedeutenden Zweck erfüllt.\n\nSetzt Eure neu erworbene Macht ein und bringt diesen Krieg zu Ende. Vernichtet Garrosh Höllschrei. Euer Volk verlangt danach, und zukünftige Generationen werden Euch als Boten der glorreichen neuen Welt preisen, die wir zusammen errichten werden.\n\nIch habe keine Belohnung für Euch. Ich habe bereits alles in meiner Macht Stehende getan, um sicherzugehen, dass Ihr erfolgreich seid. Ihr seid auf Euch allein gestellt.\n\nSetzt Höllschreis Herrschaft ein Ende.", sourceObjective = "Schließt die Schlacht um Orgrimmar ab und besiegt Garrosh Höllschrei.", sourceObjectiveStatus = "unverified-source-field" }
quests[33107] = { id = 33107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechtes Gefühl, schlechteres Ergebnis", description = "<Als Ihr die Schriftrolle öffnet, stellt Ihr fest, dass sich Eure schlimmsten Befürchtungen bewahrheitet haben: Die Sha-Energien haben das Lin-Rezept verderbt.>\n\n<Eure einzige Möglichkeit besteht darin, die freigesetzten Energien zu besiegen und zu hoffen, dass die Schriftrolle gerettet werden kann.>", sourceObjective = "Besiegt den Geist von Lin Da-Gu.", sourceObjectiveStatus = "unverified-source-field" }
quests[33109] = { id = 33109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33111] = { id = 33111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfgeld: Krankes Urtum", description = "Die Urtume des Verfluchten Waldes wurden durch dämonische Magie verderbt. Da sie nun ohnehin vernichtet werden müssen, können wir uns auch ihrer Ressourcen bedienen. Spart in der Zeit, dann habt Ihr in der Not.\n\nNehmt Euch in Acht: Diese Waldungetüme stellen keine einfachen Ziele dar. Schart ein paar gute Freunde um Euch, bevor Ihr diese kranken Urtume angreift.\n\n- Baros Alexston", sourceObjective = "Beschafft verderbtes Holz von einem kranken Urtum.", sourceObjectiveStatus = "unverified-source-field" }
quests[33112] = { id = 33112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Böse Omen", description = "Nun da Priesterin Mondfang das gesegnete Wasser fertig hat, wird es Zeit, dass wir uns um den Dämon kümmern.\n\nNehmt bitte das Wasser und die Schriften von Elune.\n\nMit der Macht dieser beiden Gegenstände werdet Ihr den Dämon zwingen, uns zu zeigen, was die Orcs in Gul'var vorhaben.", sourceObjective = "Zwingt das allsehende Auge.", completion = "Gul'dan ist dort! Wir müssen uns schnell in Bewegung setzen, um ihn zu fangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33113] = { id = 33113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenmondbrunnen", description = "Der Erzmagier hat mich gebeten, diesen Mondbrunnen vorzubereiten. Sobald ich so weit bin, kann ich das Brunnenwasser weihen, damit es gegen den Dämon eingesetzt werden kann.\n\nEs bleibt nur noch eins zu tun.\n\nEin Stück von einem der Monde Draenors ist in einen Teich auf der anderen Seite der Wälder gefallen. Solch ein Stein wäre für die Weihung des Mondbrunnens für Elune perfekt geeignet.\n\nWürdet Ihr es mir holen, {name}?", sourceObjective = "Besorgt einen Mondsteinbrocken.", progress = "Mit diesem Brocken gefallenen Gesteins kann ich die Weihung des Mondbrunnens vollenden.", completion = "Danke, {name}. Die Weiße Dame wird erfreut sein.\n\nNun werde ich mich meiner Aufgabe zuwenden und das Wasser des Mondbrunnens für den Plan des Erzmagiers vorbereiten.\n\nAber zuvor möchte ich Euch fragen, ob Ihr mir noch einmal helfen könnt. Die Wächterin kam mit sehr beunruhigenden Geschichten über die Kreaturen in den Wäldern zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33114] = { id = 33114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schmieden der Seelenfalle", description = "Krosnis' feuriges Herz befindet sich in der Schmiede, und wir haben die Seelensplitter.\n\nJetzt müssen wir nur noch das Feuer schüren und all diese üblen Komponenten zu einer Falle für Gul'dan zusammenfügen.", sourceObjective = "Schmiedet Gul'dans Seelenfalle.", progress = "Mit den kombinierten Seelensplittern werden wir Gul'dan fangen und dem Schattenrat auf Draenor ein Ende setzen!", completion = "Ihr habt die Seelenfalle geschmiedet. Die Zeit ist knapp, {name}.\n\nWir müssen Gul'dan gefangen nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33115] = { id = 33115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steine der Verhüllung", description = "Vor langer Zeit stellten die Schamanen des Schattenmondklans drei Steine in den Wäldern auf. Der Klan führte dort seine heiligen Rituale durch, segnete die Tiere und die Bäume.\n\nJetzt hat jemand diese Steine mit einem üblen Zauber belegt. Diese Verderbnis verhüllt das Dorf Gul'var.\n\nBevor wir über den gefangenen Dämon sicher das Dorf des Schattenrats ausspähen können, müssen wir diese Steine zerstören.", sourceObjective = "Zerstört den zentralen, nördlichen und südlichen Stein der Verhüllung.", completion = "Wo nun der Schleier von den Wäldern gehoben wurde, können wir den Dämon einsetzen.\n\nWir werden ihn überzeugen, sein Auge auf Gul'var zu richten und uns zu zeigen, was der Schattenrat plant.", sourceObjectiveStatus = "unverified-source-field" }
quests[33116] = { id = 33116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man einen Schatten fängt", description = "Gul'dan befindet sich auf der Schattenanhöhe, auf dem Hügel im Westen. Aber Ihr müsst Euch beeilen, {name}. Wir wissen, dass er bald nach Talador und zum Frostfeuergrat aufbricht.\n\nDie Verwendung der Seelenfalle ist nicht allzu kompliziert. Richtet sie einfach auf Gul'dan und schießt, um ihn einzufangen. Der Kristall erledigt dann den Rest.\n\nWir sehen uns beim Außenposten Sternenfall wieder, wenn Ihr Gul'dan gefangen habt.\n\nViel Glück.", sourceObjective = "Setzt Gul'dans Seelenfalle gegen Gul'dan ein.", completion = "Bedauerlich, aber nicht überraschend. Wenigstens konnten wir eins der Mitglieder des inneren Rats besiegen.\n\nEs ist nicht alles verloren, {name}. Wir wissen, was der Schattenrat vorhat und was sein Ziel ist.\n\nWir werden uns in Talador sammeln. Gemeinsam werden wir Teron'gor und seinen Plänen für Auchindoun ein Ende setzen.\n\nHabt Ihr das gehört?", sourceObjectiveStatus = "unverified-source-field" }
quests[33117] = { id = 33117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33118] = { id = 33118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33119] = { id = 33119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sklaverei und Zwietracht", description = "Wir haben zwar ihre Festung, aber einige meiner Leute sitzen immer noch als Sklaven in der Rußgeschwärzten Mine fest.\n\nWir können keine Leute entbehren, aber Ihr scheint mehr als fähig zu sein, mit ein paar Ogern allein fertigzuwerden.\n\nIch bitte Euch, befreit alle versklavten Frostwölfe, die Ihr dort findet, und haltet nach Mulverick Ausschau.", sourceObjective = "Befreit 5 versklavte Frostwolforcs aus dem Rußgeschwärzten Bergbaulager oder der Rußgeschwärzten Mine und haltet nach Mulverick Ausschau.", completion = "Wer seid Ihr, Fremder? Ich habe gesehen, wie Ihr einige von uns gerettet habt...", sourceObjectiveStatus = "unverified-source-field" }
quests[33120] = { id = 33120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Fluch lastet auf den Wäldern", description = "Cordana hat mir erzählt, dass die Kreaturen des Waldes durch dieselben teuflischen Energien verflucht worden sind, die Khadgar daran hindern, in das Dorf der Orcs zu spähen.\n\nDas können wir nicht zulassen.\n\nWenn wir in Azeroth wären, könnte ich schnell genug ein Heilmittel finden. Doch leider sind wir dort nicht; und darüber hinaus fehlt uns die Zeit.\n\nWir setzen dem Leiden dieser armen Kreaturen besser ein schnelles Ende, als ihnen zu gestatten, mit dieser dämonischen Energie fortzubestehen.", sourceObjective = "Tötet 10 teufelsverfluchte Kreaturen im Verfluchten Wald.", completion = "Keine schöne Aufgabe. Ich wünschte, ich hätte eine Alternative gehabt.\n\nDanke für Eure Aufopferung, {name}. Lasst Euch von der Tatsache trösten, dass Euch Elunes Verständnis sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[33124] = { id = 33124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angeln mit Fin - Tracking Quest" }
quests[33125] = { id = 33125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würdiger Abschied", description = "Die Oger waren in der Überzahl, <hustet> aber wir haben sie für ihre Taten mit Blut bezahlen lassen.\n\nTrotzdem war ich gezwungen, meine gefallenen Brüder und Schwestern auf dem Schlachtfeld zurückzulassen. Sie verdienen es nicht, dass ihre Leichname von diesem Ogerdreck geschändet werden.\n\nHier, nehmt diese Fackel <hustet> und tut, was ich nicht konnte: Verbrennt die Leichname meiner gefallenen Brüder und Schwestern im Westen.", sourceObjective = "Verbrennt die Leichname der Vorhut der Frostwölfe.", progress = "Habt Ihr den anderen ein ordentliches Begräbnis gegeben?", completion = "{name}, Ihr habt dem Klan Ehre erwiesen, indem Ihr meiner Familie ein ordentliches Begräbnis gewährt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[33132] = { id = 33132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Und zu Guttra Letzt...", description = "Schneepfote hat mir geholfen, hierher zu gelangen, damit ich gegen ihren Anführer Guttra kämpfen kann, doch habe ich zu viel Blut verloren. Mein Ende naht.\n\nTragt Ihr die Stärke in Euch, mir dabei zu helfen, meine gefallenen Brüder und Schwestern zu rächen und Guttra Wolfsbiss zu töten?\n\nDas Monster bewohnt den höchsten Turm auf dem Grimfrostberg.", sourceObjective = "Tötet Guttra Wolfsbiss.", completion = "Wolfsbiss ist besiegt? <hustet> Prächtig.", sourceObjectiveStatus = "unverified-source-field" }
quests[33133] = { id = 33133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsembleme", description = "Seid gegrüßt, {name}. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einem Kriegsemblem werden bei Eurer Verfolgung von Garrosh wertvolle Artefakte sehr viel häufiger in Euren Besitz gelangen.", sourceObjective = "Sammelt 50 geringe Amulette des Glücks.", progress = "Mögen diese Talismane Euch Glück bringen, {name}.", completion = "Mögen die Sterne mit einem Lächeln auf Euch herabblicken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33134] = { id = 33134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsembleme", description = "Seid gegrüßt, {name}. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einem Kriegsemblem werden bei Eurer Verfolgung von Garrosh und seinen Streitkräften wertvolle Artefakte sehr viel häufiger in Euren Besitz gelangen.", sourceObjective = "Sammelt 50 geringe Amulette des Glücks.", progress = "Mögen diese Talismane Euch Glück bringen, {name}.", completion = "Mögen die Sterne mit einem Lächeln auf Euch herabblicken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33135] = { id = 33135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung von Gul'var", description = "Nur, weil wir uns auf Gul'dan konzentrieren müssen, heißt das noch lange nicht, dass wir dabei nicht auch den Schattenrat zu Fall bringen werden.\n\nDieses Dorf stinkt geradezu nach den Handlangern des Schattenrats. Wir müssen etwas gegen sie unternehmen.", sourceObjective = "Tötet 20 Orcs des Schattenrats in Gul'var.", completion = "Jede Welt ist ohne diese Dämonenhuldiger besser dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[33136] = { id = 33136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schlechten Zeiten sind da", sourceObjective = "{name}, ich kann den Ausdruck in Euren Augen sehen. Ich habe von Euren Heldentaten im Turnier gehört. Ihr seid bereit, einen Gefährten zu erwählen!\n\nDieses Mal werde ich Euch diese zwei Münzen zusätzlich überreichen. Setzt sie weise ein, denn von nun an könnt Ihr Euch jede Woche nur eine Münze verdienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33137] = { id = 33137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Turnier der Erhabenen", description = "Auf der Zeitlosen Insel findet ein besonderes Turnier statt, das ersonnen wurde, um die Führungsqualitäten der Teilnehmer zu testen. Diejenigen, die sich als würdig erweisen, erhalten die Gelegenheit, mit einer Verkörperung der Tugend Freundschaft zu schließen – mit den Nachkommen der Erhabenen persönlich.\n\nJedes Mal, wenn Ihr das Turnier gewinnt, ehre ich Euch mit einer einzelnen zeremoniellen Münze. Wenn Ihr über genügend Münzen verfügt, sprecht mich erneut an, um Eure Belohnung weiter zu erörtern.", sourceObjective = "Sprecht mit Meister Li, um am Turnier der Erhabenen teilzunehmen und besiegt dort alle Herausforderer.", completion = "Vor mir steht ein wahrer Anführer. Es ist mir eine Ehre, Euch diese Münze zu verleihen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[33138] = { id = 33138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warum kämpfen wir?", description = "Oh, <mein Freund/meine Freundin>, heute habt Ihr zusammen mit Euren Gefährten dem Sha, das Pandaria seit Anbeginn aller Zeiten geplagt hat, ein Ende bereitet. Ihr habt erreicht, was nicht einmal die Titanen mit ihren Mogudienern erreicht haben: Ihr habt den letzten Atem von Y'Shaarj erstickt.\n\nKommt, geleitet Ihr mich in das Tal der Ewigen Blüten? Es gibt dort etwas, das Ihr sehen müsst.", sourceObjective = "Lehrensucher Cho möchte sich mit Euch im Tal der Ewigen Blüten unterhalten.", completion = "Unser geliebtes Tal der Ewigen Blüten. So viel Zerstörung und Gewalt. Aber... ich verspüre einen Funken Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[33139] = { id = 33139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf ewig verlorene Geheimnisse?", description = "<Mit dem alten Nudelsuppenrezept der Familie Lin in den Händen entscheidet Ihr Euch, zum Halbhügelmarkt aufzubrechen.>\n\n<Wenn irgendjemand in Pandaria diese Schriftrolle entziffern kann, dann ist das Sungshin Eisentatz.>", sourceObjective = "Sprecht mit Sungshin Eisentatz auf dem Halbhügelmarkt im Tal der Vier Winde.", sourceObjectiveStatus = "unverified-source-field" }
quests[33145] = { id = 33145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmfrostberg", description = "Befreit die Frostwölfe, die von den Grimmfrostogern gefangen gehalten werden." }
quests[33146] = { id = 33146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nudelzeit", description = "Hallo, {name}. Möchtet Ihr wieder einmal am Nudelstand arbeiten?\n\nSagt mir einfach Bescheid, wenn Ihr noch eine Schicht übernehmen könnt, dann bereite ich alles vor.", sourceObjective = "Reiht Euch für eine Schicht am Nudelstand von Halbhügel ein und beendet sie.", completion = "Großartige Arbeit, {name}! Alle sind immer voll freudiger Erwartung, wenn sie hören, dass Ihr Nudelsuppe macht. Die Leute kommen aus ganz Pandaria her, nur um sie zu probieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[33147] = { id = 33147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Y'Shaarjs letzter Atemzug", description = "Eine dunkle, dampfende Substanz befleckt den Boden des Raums. Das ist alles, was vom Alten Gott Y'Shaarj übrig bleibt.", sourceObjective = "Sprecht mit Lehrensucher Cho in der Schlacht um Orgrimmar.", completion = "Versteht Ihr? In diesem Moment schwindet seine Existenz.", sourceObjectiveStatus = "unverified-source-field" }
quests[33151] = { id = 33151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgungsquest: Beobachtete die Ankunft von Späher Valdez" }
quests[33156] = { id = 33156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüter der Zeit Kairoz", description = "Ihr habt den Weg zur Zeitlosen Insel gefunden, {class}. Der bronzene Drachenschwarm ist sehr daran interessiert, die Geheimnisse dieses Ortes zu untersuchen, doch die Insel ist gefährlich und wir werden Eure Hilfe benötigen.\n\nWenn Ihr den Strand etwa zur Hälfte entlang geht, stoßt Ihr auf einen gepflasterten Weg, der nach Osten führt.\n\nDieser bringt Euch zum uralten Hof der Erhabenen. Dort werdet Ihr Kairoz antreffen, einen der Hüter der Zeit, mit denen wir zusammenarbeiten.\n\nKairoz kann Euch Eure Fragen beantworten. Doch seid vorsichtig, auf dem Weg zu ihm können Gefahren lauern.", sourceObjective = "Sprecht mit Kairoz auf der Zeitlosen Insel.", completion = "Ah! Seid gegrüßt, {name}!\n\nMir wurde von Eurer Ankunft berichtet, doch hatte ich noch nicht so bald mit Euch gerechnet.\n\n…oder ist vielleicht schon eine ganze Weile vergangen? Das lässt sich hier wahrlich schwer ausmachen.\n\nAlso! Sollen wir anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[33157] = { id = 33157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Phased Terrain Swap 1" }
quests[33158] = { id = 33158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Phased Terrain Swap 2" }
quests[33159] = { id = 33159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Phased Terrain Swap 3" }
quests[33160] = { id = 33160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüter der Zeit Kairoz", description = "Ihr habt den Weg zur Zeitlosen Insel gefunden, {class}. Der bronzene Drachenschwarm ist sehr daran interessiert, die Geheimnisse dieses Ortes zu untersuchen, doch die Insel ist gefährlich und wir werden Eure Hilfe benötigen.\n\nWenn Ihr den Strand etwa zur Hälfte entlang geht, stoßt Ihr auf einen gepflasterten Weg, der nach Osten führt.\n\nDieser bringt Euch zum uralten Hof der Erhabenen. Dort werdet Ihr Kairoz antreffen, einen der Hüter der Zeit, mit denen wir zusammenarbeiten.\n\nKairoz kann Euch Eure Fragen beantworten. Doch seid vorsichtig, auf dem Weg zu ihm können Gefahren lauern.", sourceObjective = "Sprecht mit Kairoz auf der Zeitlosen Insel.", completion = "Ah! Seid gegrüßt, {name}!\n\nMir wurde von Eurer Ankunft berichtet, doch hatte ich noch nicht so bald mit Euch gerechnet.\n\n…oder ist vielleicht schon eine ganze Weile vergangen? Das lässt sich hier wahrlich schwer ausmachen.\n\nAlso! Sollen wir anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[33161] = { id = 33161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zeitlose Entdeckungsreise", description = "Ihr solltet Euch zunächst mit der Insel vertraut machen.\n\nGeht auf Entdeckungstour. Untersucht alles, was Euer Interesse weckt. Kehrt zurück, wenn Ihr damit fertig seid, und ich werde Euch für die von Euch gesammelten Informationen über diesen merkwürdigen Ort belohnen.\n\nUnd seid ja vorsichtig! Hier gibt es monströse Biester und übernatürliche Kreaturen im Überfluss.", sourceObjective = "Erkundet die Zeitlose Insel.", completion = "Ein bizarrer Ort, nicht wahr?\n\nIch hoffe doch, dass Ihr unterwegs ein paar Abenteuer erlebt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[33162] = { id = 33162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weekly Vignette Boss Kill - Tracking Quest" }
