quests[33165] = { id = 33165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: The Root of Darkness - Stone 2" }
quests[33166] = { id = 33166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: The Root of Darkness - Stone 3" }
quests[33167] = { id = 33167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: The Root of Darkness - Stone 4" }
quests[33168] = { id = 33168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herz in Flammen", description = "Wir haben die Splitter, jedoch müssen sie nun kombiniert werden. Hier befindet sich eine Schmiede, aber sogar ihr Feuer ist für unseren Zweck nicht heiß genug.\n\nEs gibt allerdings einen Dämon in der Nähe, der so heiß brennt wie die Sonne.\n\nGul'dan, oder vielleicht auch Razuun, hat es geschafft, eine Höllenbestie zu beschwören. Sie selbst nennt sich Krosnis, was so viel wie \"Schmelzofen\" bedeutet.\n\nDas Herz des Dämons brennt heiß genug. Ihr müsst es nur noch herbringen.", sourceObjective = "Beschafft das feurige Herz von Krosnis.", progress = "Mit der kombinierten Macht der Splitter sollten wir Gul'dan fangen können.", completion = "Schnell, legt das Herz in die Schmiede. Wir werden mit seiner höllischen Hitze die Falle schmieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33170] = { id = 33170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One-Time Chest 000" }
