quests[33210] = { id = 33210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One-Time Chest - Blazing Chest" }
quests[33211] = { id = 33211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine zeitlose Frage", description = "Schicksal. Bestimmung. Karma. Begriffe wie diese legen nahe, dass die Zeitlinien unantastbar sind.\n\nIch wünschte, dem wäre so. Bis zum heutigen Tage sehnen sich viele Bewohner Azeroths danach, die Vergangenheit ändern zu können. Doch genau so, wie unsere Erfahrungen uns formen, formen sie auch die Welt um uns herum.\n\nBedenkt, wie diese Fäden das Gewebe der heutigen Realität geschaffen haben. Wenn genug Fäden gelöst werden, wird die Kausalität unweigerlich versagen und so das Gewebe auftrennen. Es reicht sogar aus, nur einen einzigen Faden zu lösen, um ein Desaster hervorzurufen – so es denn der richtige Faden ist.", sourceObjective = "Gebt die richtige Antwort auf eine von Evelynas Fragen zur Geschichte von Azeroth.", progress = "So lasst uns über die Ereignisse sprechen, die bereits geschehen sind.", completion = "Dies ist die große Verantwortung eines Historikers – sollten Azeroths Zeitlinien angegriffen werden, müssen wir die Geschichte genau so rekonstruieren, wie sie geschehen ist, oder es könnte furchtbare Folgen haben. Und so erschaffen wir eine stärkere Zukunft für uns alle, indem wir unsere Erzählungen und unser Wissen verbreiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33216] = { id = 33216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One-Time Chest - T1G1" }
