quests[33221] = { id = 33221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One-Time Chest - T3" }
quests[33222] = { id = 33222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klein Tommy Grünschnabel", description = "Ich hab' auch ein Kampfhaustier! Wollt Ihr kämpfen? Es macht ganz viel Spaß, versprochen!", sourceObjective = "Besiegt Klein Tommy Grünschnabel in einem Haustierkampf.", completion = "Ihr habt geschummelt! Ich weiß es ganz genau!", sourceObjectiveStatus = "unverified-source-field" }
quests[33225] = { id = 33225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33226] = { id = 33226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33227] = { id = 33227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One-Time Chest 028" }
quests[33228] = { id = 33228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeit in Euren Händen", description = "Die Bewohner dieser eigenartigen Insel handeln mit einer besonderen Währung, der die unbeständigen Fluktuationen der Zeit nichts anhaben können.\n\nIhr solltet so viele dieser \"zeitlosen Münzen\" sammeln, wie Ihr nur könnt! Ihr könnt sie in kleinen Truhen finden oder sie auf der ganzen Insel von Kreaturen einsammeln. Größere, seltenere Kreaturen stellen eine bessere Quelle für Münzen dar – es könnte lukrativ für Euch sein, Euch in einer Gruppe fortzubewegen.\n\nStellt Euch den Nebelwirkern Ai und Ku auf der anderen Seite des Hofes der Erhabenen vor und sammelt einige Münzen für mich.", sourceObjective = "Sammelt 1000 zeitlose Münzen und stellt Euch den Nebelwirkern Ai und Ku vor.", progress = "Ihr seid schon zurück? Es scheint mir, als ob wir erst vor wenigen Momenten miteinander gesprochen haben.", completion = "Ich glaube, dass Ihr langsam ein Gespür für diesen Ort bekommt! Ja, es gibt zahlreiche Möglichkeiten, zeitlose Schätze zu erlangen. Hier gehen ständig merkwürdige Dinge vor sich, also haltet Eure Augen offen.\n\nSprecht mit den Nebelwirkern, die Ihr bereits getroffen habt, um Eure mühsam erarbeiteten Münzen auszugeben. In der Zwischenzeit werde ich meine Forschung fortsetzen.\n\nHier ist ein Vorgeschmack auf die Schätze, die Ihr hier finden könnt. Es gibt auch noch mächtigere Gegenstände. Ihr werdet sehen, dass versteckte Truhen an den gefährlicheren Orten der Insel ziemlich beachtliche... Belohnungen bereithalten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[33229] = { id = 33229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bronzener Schimmer", description = "Während Ihr die Zerstörung des Tals betrachtet, bemerkt Ihr etwas bronzen Schimmerndes. Falls Ihr Euch nicht irrt, versucht ein winziger Gnom vom Balkon beim Heim des Wissens oberhalb des Mogu'shanpalasts Eure Aufmerksamkeit zu erlangen.\n\nIhr solltet herausfinden, was sie von Euch möchte.", sourceObjective = "Sprecht mit Chromie beim Heim des Wissens im Tal der Ewigen Blüten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33230] = { id = 33230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein bronzener Schimmer", description = "Während Ihr die Zerstörung des Tals betrachtet, bemerkt Ihr etwas bronzen Schimmerndes. Falls Ihr Euch nicht irrt, versucht ein winziger Gnom vom Balkon beim Heim des Wissens oberhalb des Mogu'shanpalasts Eure Aufmerksamkeit zu erlangen.\n\nIhr solltet herausfinden, was sie von Euch möchte.", sourceObjective = "Sprecht mit Chromie beim Heim des Wissens im Tal der Ewigen Blüten.", completion = "<Die Augen des kleinen Gnoms glänzen kupferfarben im Licht. Sie ist nicht, was sie zu sein scheint.>\n\n{name}! Ich habe auf Euch gewartet. Der bronzene Drachenschwarm benötigt Eure Dienste.", sourceObjectiveStatus = "unverified-source-field" }
quests[33231] = { id = 33231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reise zur Zeitlosen Insel", description = "Der bronzene Drachenschwarm hat in Pandaria ein höchst ungewöhnliches Phänomen entdeckt, {class}. Eine Insel, die aus den Nebeln weit vor der Küste des Jadewalds aufgetaucht ist und bis jetzt in der Zeit verloren war!\n\nEs ist ein gefährlicher Ort, vielleicht gar der gefährlichste in ganz Pandaria, doch wir sind fest entschlossen, seinen Geheimnissen auf die Spur zu kommen.\n\nHier, nehmt diese Taschenuhr. Ein einfacher Klick bringt Euch auf die Insel. Findet Euch dort zurecht und sprecht mit Behüterin Lara. Sie wird Euch den Weg zu unserem wichtigsten Forscher weisen.", sourceObjective = "Sprecht mit Behüterin Lara auf der Zeitlosen Insel, die vor der Küste des Jadewalds gelegen ist.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, hat Chronormu nicht zu viel versprochen. Ihr seid genau zur rechten Zeit erschienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33232] = { id = 33232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reise zur Zeitlosen Insel", description = "Der bronzene Drachenschwarm hat in Pandaria ein höchst ungewöhnliches Phänomen entdeckt, {class}. Eine Insel, die aus den Nebeln weit vor der Küste des Jadewalds aufgetaucht ist und bis jetzt in der Zeit verloren war!\n\nEs ist ein gefährlicher Ort, vielleicht gar der gefährlichste in ganz Pandaria, doch wir sind fest entschlossen, seinen Geheimnissen auf die Spur zu kommen.\n\nHier, nehmt diese Taschenuhr. Ein einfacher Klick bringt Euch auf die Insel. Findet Euch dort zurecht und sprecht mit Behüterin Alundra. Sie wird Euch den Weg zu unserem wichtigsten Forscher weisen.", sourceObjective = "Sprecht mit Behüterin Alundra auf der Zeitlosen Insel, die vor der Küste des Jadewalds gelegen ist.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, hat Chronormu nicht zu viel versprochen. Ihr seid genau zur rechten Zeit erschienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33233] = { id = 33233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33234] = { id = 33234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fleischige Kranichkeule", progress = "Was habt Ihr da?", completion = "Meine Güte, das Ding ist aber wirklich fleischig! Denkt mal an die Suppe, die ich damit zubereiten kann! Hier, ich gebe Euch ein paar zeitlose Münzen dafür." }
quests[33235] = { id = 33235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Großschildkrötenfleisch", progress = "Na, das riecht ja... interessant...", completion = "Es ist so... schwammig! Hmm, ja, vielleicht mit ein wenig Sojasoße und ein bisschen Öl... Hier, nehmt diese Münzen als Bezahlung!" }
quests[33236] = { id = 33236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwere Yakrippe", progress = "Was riecht denn da nach blutigen Rippchen?", completion = "Ach, das bringt Fleisch auf die Rippen! Ha, ha, ja, das ist Küchenhumor. Hier sind ein paar Münzen dafür, dass Ihr nicht gestöhnt habt!" }
quests[33238] = { id = 33238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dicke Tigerkeule", progress = "Ah, jetzt wird die große Keule ausgepackt!", completion = "Die Streifen auf dieser Keule sind so interessant. Ich frage mich, was wohl beim Garen mit ihnen passiert? Zunächst muss ich das Fleisch aber ein wenig weich klopfen. Endlich kommt der Fleischklopfer mal wieder zum Einsatz! Hier habt Ihr etwas für Eure Mühen!" }
quests[33239] = { id = 33239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Makelloses Feuersturmei", progress = "Was ist denn das für ein himmlischer Geruch?", completion = "So ein Ei habe ich noch nie gesehen, wo in aller Welt habt Ihr das bloß her? Es ist so schön, ich weiß gar nicht, ob ich es zerschlagen kann. Ach, nur ein Scherz, damit werde ich das allerbeste Omelette machen! Hier sind ein paar Münzen!" }
quests[33248] = { id = 33248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerprobe", description = "He, Ihr da! {name}, richtig? Seid gegrüßt. Ich bin Taijing.\n\n<Taijing mustert Euch von Kopf bis Fuß.>\n\nIhr seht stark aus. Ich habe Euch schon ein paar Mal hier im Tal gesehen, aber noch nicht im Kampf erlebt. Ich frage mich, ob Ihr so stark seid, wie Ihr ausseht.\n\nSolltet Ihr daran interessiert sein, Euch zu beweisen, sprecht mit Prüfungsmeister Rotun im Tempel des Weißen Tigers, am Kun-Lai-Gipfel. Er wird Euch einer Prüfung unterziehen.", sourceObjective = "Sprecht mit Prüfungsmeister Rotun im Tempel des Weißen Tigers und betretet dann die Feuerprobe.", completion = "Willkommen bei der Feuerprobe, {class}. Ich bin Prüfungsmeister Rotun.\n\nHier könnt Ihr Eure Fähigkeiten in verschiedenen Kampfdisziplinen unter Beweis stellen: im Verursachen von Schaden, im Abwehren und Aushalten von Schaden und im Heilen. Ich werde diese Prüfungen leiten und bewerten.\n\n\n\nSeid Ihr bereit, anzufangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[33249] = { id = 33249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuerprobe", description = "He, Ihr da! {name}, richtig? Seid gegrüßt. Ich bin Jinho.\n\n<Jinho mustert Euch von Kopf bis Fuß.>\n\nIhr seht stark aus. Ich habe Euch schon ein paar Mal hier im Tal gesehen, aber noch nicht im Kampf erlebt. Ich frage mich, ob Ihr so stark seid, wie Ihr ausseht.\n\nSolltet Ihr daran interessiert sein, Euch zu beweisen, sprecht mit Prüfungsmeister Rotun im Tempel des Weißen Tigers, am Kun-Lai-Gipfel. Er wird Euch einer Prüfung unterziehen.", sourceObjective = "Sprecht mit Prüfungsmeister Rotun im Tempel des Weißen Tigers und betretet dann die Feuerprobe.", completion = "Willkommen bei der Feuerprobe, {class}. Ich bin Prüfungsmeister Rotun.\n\nHier könnt Ihr Eure Fähigkeiten in verschiedenen Kampfdisziplinen unter Beweis stellen: im Verursachen von Schaden, im Abwehren und Aushalten von Schaden und im Heilen. Ich werde diese Prüfungen leiten und bewerten.\n\n\n\nSeid Ihr bereit, anzufangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[33250] = { id = 33250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Schatz, verloren in der Zeit", progress = "Meine Güte, was ist DAS denn?", completion = "Das ist erstaunlich! Solch ein Ei ist in Pandaria seit Tausenden von Jahren nicht mehr gesehen worden. Ich glaube, einige unserer ältesten Schriften beschreiben, wie am besten damit umzugehen ist, doch viele sind in der Sprache der Mogu verfasst. Ich sollte mich wohl besser daran machen, sie zu übersetzen!" }
quests[33252] = { id = 33252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[33255] = { id = 33255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Marsch der Rechtschaffenen", description = "Die Eiserne Horde hat Karabor übernommen. Wenn wir jetzt nicht handeln, verlieren wir die Stadt.\n\nExarch Akama und die letzten unserer Streitkräfte sind in der Stadt gefangen, aber Eure Garnisonskräfte sind immer noch vor dem Tempel und erwarten Eure Befehle.\n\nKommt und fliegt mit mir mit. Wir stoßen auf dem Feld zu Euren Truppen. Gemeinsam mit den Naaru werden wir einen letzten Vorstoß unternehmen, die Stadt zurückzuerobern.", sourceObjective = "Begleitet Eure Garnisonsstreitkräfte zum Tempel von Karabor, indem Ihr alle Orcs auf dem Pfad des Lichts tötet.", completion = "Jetzt müssen wir diese Orcs nur noch ein für alle Mal vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[33256] = { id = 33256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung von Karabor", description = "Verteidigt Karabor gegen die Eiserne Horde.\n\nAm Ende des nördlichen Hofs befindet sich Arnokk der Brenner. Er bewacht den Zugang zum Hafen hinter Karabor. Dort wartet der größte Teil der Armee der Eisernen Horde.\n\nSobald wir uns seiner entledigt haben, müssen wir uns um den Anführer der Eisernen Horde kümmern, Kommandant Vorka.", sourceObjective = "Vernichtet die Eiserne Horde in Karabor.", completion = "Wir haben es geschafft, {name}. Ohne Eure heldenhaften Bemühungen wäre der Tempel von Karabor der Eisernen Horde in die Hände gefallen.\n\nProphet Velen wäre stolz auf uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[33257] = { id = 33257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprite Fright - Tracking Quest" }
quests[33258] = { id = 33258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Karkanos" }
quests[33259] = { id = 33259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Spirit of Jadefire" }
quests[33260] = { id = 33260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Gu'chi the Swarmbringer" }
quests[33261] = { id = 33261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Emerald Gander" }
quests[33263] = { id = 33263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schummergehölz", description = "<Das scheint eines der Lastmaultiere aus Eurer Garnison zu sein. Seltsam, dass es hier draußen allein herumwandert.\n\nIhr solltet dem vielleicht auf den Grund gehen.>", sourceObjective = "Sucht im Schummergehölz nach Hinweisen.", completion = "Dem Licht sei Dank. <hust> Ich habe nicht geglaubt, dass ich hier lebend rauskommen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[33264] = { id = 33264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ordentliches Begräbnis", description = "<Der Orc ist sichtlich erschöpft. Eine große Blutlache sammelt sich zu seinen Füßen.>\n\nWir waren auf der Jagd, als wir auf die Wölfe getroffen sind. Sie wurden angegriffen.\n\nWir haben mit unseren Klingen viele Oger getötet... aber ihre Zahl war zu groß.\n\nIch muss nur kurz zu Atem kommen, dann werde ich hinausgehen und den Rest von ihnen töten.\n\nHier, nehmt diese Fackel. Gebt meinen Brüdern und Schwestern ein anständiges Begräbnis und kehrt dann zu mir zurück.", sourceObjective = "Verbrennt die Leichname der Vorhut der Frostwölfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[33266] = { id = 33266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Licht im Dunkel - Verfolgungsquest" }
quests[33267] = { id = 33267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschneiden der Schotlinge", description = "The blood soaked body of Kenny is slummped up against the cave wall. The podlings clearly made a feast of him.", sourceObjective = "Nehmt Rache an den Schotlingen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33269] = { id = 33269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Säuberung von Gul'var", description = "Khadgar möchte, dass Ihr Euch auf Gul'dan konzentriert, aber das heißt noch lange nicht, dass wir dabei nicht auch den Schattenrat zu Fall bringen.\n\nGul'var stinkt geradezu nach Handlangern des Schattenrats. Wir müssen etwas gegen sie unternehmen.", sourceObjective = "Tötet 20 Orcs des Schattenrats in Gul'var.", completion = "Jede Welt ist ohne diese Dämonenhuldiger besser dran.", sourceObjectiveStatus = "unverified-source-field" }
quests[33270] = { id = 33270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Ironfur Steelhorn" }
quests[33271] = { id = 33271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ränkespiele", description = "<Jarrod ist eindeutig verletzt. Er zuckt vor Schmerz zusammen, als er anfängt, zu berichten.>\n\nMeine Waldtruppführerin Shelly... sie wird nicht weit von hier gefangen gehalten.", sourceObjective = "Tötet König Todesblüte.", completion = "<Irgendetwas bewegt sich unter diesen ganzen Wurzeln.>", sourceObjectiveStatus = "unverified-source-field" }
quests[33272] = { id = 33272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Great Turtle Furyshell" }
quests[33273] = { id = 33273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Leafmender" }
