quests[33331] = { id = 33331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingefangene Kleintiere", description = "Dieses arme Wesen wird bald Schotlingfutter sein. Es sollte ziemlich einfach sein, diesen kleinen Kerl zu befreien.", sourceObjective = "Befreit eingefangene Kleintiere im Schummergehölz.", sourceObjectiveStatus = "unverified-source-field" }
quests[33332] = { id = 33332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweise aus der Vergangenheit", description = "Es gibt so viel zu lernen über diesen Ort, doch gibt er seine Geheimnisse nicht bereitwillig preis.\n\nEtwas, das Ihr bei unserer letzten Unterhaltung sagtet, hat meine Neugier geweckt. Diese Nebelwirkerin Ai trägt ein von der Zeit gezeichnetes Tagebuch bei sich, wenn ich mich recht erinnere? Darin finden wir vielleicht die Antworten auf unsere Fragen - oder es wirft einfach noch weitere auf. Ich schätze, es hängt alles von der Sorgfalt des Forschers ab, der an diesem widersinnigen Ort zur Feder griff.\n\nBeschafft das von der Zeit gezeichnete Tagebuch und kehrt dann zu mir zurück. Gemeinsam werden wir seine Mysterien erkunden.", sourceObjective = "Erwerbt ein von der Zeit gezeichnetes Tagebuch von Nebelwirkerin Ai.", progress = "Ah, Ihr seid zurück. Habt Ihr das Tagebuch?", completion = "Ah, Ihr habt es! Ausgezeichnet!\n\nEin oberflächlicher Blick hat gezeigt, dass ich mit meinen Annahmen gar nicht so falsch lag. Obwohl die Seiten abgenutzt und wasserdurchtränkt sind, sind die meisten Einträge doch noch lesbar. Es scheint, als hätte unser Freund, der Forscher Harrington, recht wortreich die Wesen und Schätze katalogisiert, die er auf seinen Reisen auf der Insel gefunden hat.\n\nNun, wollt Ihr da einfach nur rumstehen? Dieser Foliant ist eine wahre Fundgrube an Mysterien und wir haben kaum an der Oberfläche gekratzt! Das Abenteuer wartet!", sourceObjectiveStatus = "unverified-source-field" }
quests[33333] = { id = 33333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitlose Schätze", description = "Das Tagebuch behauptet, dass auf der Insel Schätze im Überfluss vorhanden sind, manchmal verführerisch unerreichbar, manchmal verborgen in dunklen Höhlen und Hohlräumen. Was ist hier wohl versteckt worden, vor so vielen Generationen?\n\nUnd, was vielleicht noch viel wichtiger ist: von wem?\n\nSucht auf der Insel nach solchen Schätzen und kehrt mit den Funden zu mir zurück. Seid gewarnt, dass nicht alles Gold ist, was glänzt - und dass das Gegenteil manchmal ebenfalls stimmt. Ab und zu ist ein einfacher ausgehöhlter Baumstumpf das beste Versteck für das, was von Wert ist.", sourceObjective = "Findet einen verborgenen Schatz auf der Zeitlosen Insel.", progress = "Die Zeit fließt seltsam an diesem Ort. Ich kann nicht sagen, ob ich gerade schlafen oder mein Mittagessen zu mir nehmen sollte.", completion = "Ich freue mich, dass Eure Anstrengungen mit einigen Besitztümern belohnt wurden, doch sind wir der Lösung dieses Rätsels nicht nähergekommen. Findet Trost in dem Wissen, dass solche Schätze sicherlich über die Insel verteilt sind und nur auf Eure Fähigkeiten als Forscher und Kämpfer warten.\n\nOh, noch eins, mein junger Abenteurer - vergesst nicht, ab und zu in den Himmel zu blicken.", sourceObjectiveStatus = "unverified-source-field" }
quests[33334] = { id = 33334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stark genug, um zu überleben", description = "Eine in der Zeit verlorene Insel, und doch ist sie bei ihrer Rückkehr voller Leben!\n\nWo ist diese Insel hingereist? Ist sie einfach nur in der Zeit vorwärts gesprungen oder musste sie in den dunklen Bereichen des Wirbelnden Nethers darben?\n\nEines ist jedoch sicher: Die Wesen, die hier leben, sind weit mehr als sie zu sein scheinen. Ich spüre eine verborgene Kraft in ihnen, über Äonen geformt. Stellt Euch den Champions dieser Spezies, gebührend gekennzeichnet ob ihrer Macht und ihren Fähigkeiten, und vernichtet fünf dieser Kreaturen.\n\nDurch ihren Tod finden wir vielleicht die Hinweise, die wir benötigen.", sourceObjective = "Vernichtet fünf seltene Kreaturen oder seltene Elitekreaturen auf der Zeitlosen Insel.", progress = "Dieses Tagebuch ist wirklich faszinierend. Ich frage mich, was am Ende aus unserem guten Freund, dem Forscher, geworden ist.", completion = "Eine interessante Geschichte von Kampf und Tapferkeit, doch fürchte ich, dass wir wenig aus Euren Anstrengungen gelernt haben, außer dass Ihr ein wahrer Abenteurer seid. Es scheint, als würden wir ständig in Sackgassen geraten, wie sich diese Geschichte auch dreht und wendet. Die Zeit ist eine launische Herrin.\n\nVielleicht möchtet Ihr ein wenig Zeit damit verbringen, Eure Fähigkeiten zu verbessern, bevor die Sonne untergeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[33335] = { id = 33335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Kaiser", description = "So wie ich das sehe, war dieser Ort einst eine Art Turniergelände, auf dem Krieger aus ganz Pandaria ihre Stärke unter Beweis stellten und in die Fußstapfen ihres letzten Kaisers, Shaohao, traten.\n\nIch habe gehört, dass Shaohao eins mit dem Land wurde, nachdem er seine Prüfungen bestanden hatte, und Pandaria in einen dichten Nebel hüllte, der es sogar vor unseren Fähigkeiten, die Verläufe der Zeit zu durchdringen, verbarg.\n\nDas hört sich faszinierend an, vielleicht solltet Ihr Euch mit ihm unterhalten?", sourceObjective = "Sprecht mit Kaiser Shaohao.", progress = "Seid gegrüßt, ich bin Shaohao. Seid Ihr hier, um der Weisheit der Erhabenen zu lauschen?", completion = "Ich war so stolz und versuchte, Pandaria als Geheimnis zu bewahren, und wieder einmal hat dieses Land mir eine große Lektion erteilt. Ich bin froh, dass ich meine Geschichten erneut mit meinem Volk teilen kann, sodass sie so wie ich ihre Lehren daraus ziehen können und aus meinen Fehlern lernen. Vielleicht könnt auch Ihr immer noch ein oder zwei Dinge aus den Lehren von Pandaria lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33336] = { id = 33336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Essenz der Zeit", description = "Es ist an der Zeit, dass ich Euch meine Aufgabe auf dieser Insel offenbare.\n\nDie Kräfte des bronzenen Drachenschwarms haben stark nachgelassen - uns gelingen jetzt nur noch flüchtige Eindrücke der Zeit. Es ist... recht frustrierend.\n\nDoch verfügen wir noch immer über andere Mittel und Wege. In meiner Hand halte ich die Vision der Zeit, ein von mir selbst hergestelltes Artefakt. Die Wesen dieser Insel sind durch die Zeit gereist und tragen möglicherweise immer noch etwas von ihrer Essenz in sich. Damit werden wir das Stundenglas füllen, damit es uns ein weiteres Mal einen Blick in die Zeitlinien gewährt.", sourceObjective = "Erhaltet einen Epochenstein von einer Kreatur der Zeitlosen Insel.", progress = "Habt Ihr schon etwas gefunden?", completion = "Epochensteine sind recht selten. Als kristallisierte Essenz der Zeit müssen sie sich rasch durch die Zeitalter bewegen, um sich zu formen. Ihre Präsenz hier zeigt, dass die Insel möglicherweise nicht in einer Zeit existiert, sondern sich vielmehr schnell von Zeitlinie zu Zeitlinie bewegt.\n\nDas ist im Augenblick jedoch von geringer Bedeutung. Wichtige Momente in der Zeit benötigen unsere Aufmerksamkeit. Gebt mir einen Augenblick, um diesen Stein zu mahlen und den Staub ins Stundenglas zu geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[33337] = { id = 33337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vision in der Zeit", description = "Seht, wie die Vision reagiert! Erstaunlich! Man kann Schatten der Zeitlinien erkennen, die ohne Unterlass um uns herumhuschen. Die fein gemahlenen Epochensteine entsprechen zwar nicht dem Sand, mit dem das Stundenglas der Zeit normalerweise gefüllt ist, doch sie verfügen über eine ihnen ganz eigene Macht. Unsere erste Aufgabe ist es, mit ihnen die Vision der Zeit zu kalibrieren.\n\nBringt die Vision der Zeit zu einem Ort, an dem gerade Geschichte geschrieben wird: die Schlacht um Orgrimmar. Sobald Ihr dort angekommen seid, dreht die Sanduhr um und seht, was passiert.", sourceObjective = "Verwendet die Vision der Zeit in der Schlacht um Orgrimmar.", completion = "Faszinierend. Ich werde noch einige weitere Modifikationen vornehmen und vielleicht auch einen besseren Katalysator ausfindig machen müssen. Danke, dass Ihr dieses Experiment durchgeführt habt. Ihr habt keine Nebenwirkungen festgestellt, oder? Solltet Ihr Euch der Aufgabe gewachsen fühlen, habe ich eventuell schon bald wieder etwas für Euch zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[33338] = { id = 33338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht des Stundenglases", description = "Das Stundenglas gewährt uns flüchtige Einblicke in die Zeitströme, auf denen wir früher gewandelt sind, so einfach wie auf ausgetretenen Wegen.\n\nSammelt zusätzliche Epochensteine, damit wir die Macht des Stundenglases weiterhin nutzen und die Mysterien der Zeitlinien erkunden können.\n\nDie Zukunft hängt davon ab.", sourceObjective = "Sammelt Epochensteine von den Kreaturen der Zeitlosen Insel.", progress = "Epochensteine sind seltene, kristallisierte Essenzen der Zeit.", completion = "Gebt mir einen Augenblick, um diese Steine zu mahlen und den Staub ins Stundenglas zu geben, dann werden wir sehen, welche neuen Ereignisse sich ergeben.\n\nDas trifft sich ausgezeichnet, ich habe nämlich eine besondere Affinität für konkrete Momente, anstatt für langfristige Ereignisfolgen.\n\nDie Zeitlinien sagen mir, dass wir die Macht des Stundenglases in der nahen Zukunft noch viele Male brauchen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[33340] = { id = 33340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitlose Nahrung", description = "Ihr habt es schon erahnt: die Flora und Fauna dieser Insel ist äußerst ungewöhnlich. Allerdings müssen nicht alle Erklärungen etwas Mysteriöses an sich haben. Manchmal müssen wir dem Land zuhören, um die Geschichten der Welt um uns herum zu hören. Habt Ihr schon mal darüber nachgedacht, dass die Kreaturen dieser Insel solche Ausmaße erreicht haben, einfach weil sie sich von dem Land ernährten, auf dem Ihr jetzt wandelt?\n\nIhr werdet auf dieser Insel ein reichhaltiges Nahrungsangebot finden: reife Früchte, Eier, Fleisch, Pflanzen, Nüsse und sogar die Steine. Esst und entdeckt die Macht des Landes.", sourceObjective = "Verzehrt eine reife Knackfrucht, ein sandbedecktes Ei, einen aufgeladenen Kristall, einen riesigen Yakbraten, einen gerösteten Samen oder einen Feuermohn auf der Zeitlosen Insel.", progress = "Habt Ihr Euch am Reichtum der Insel laben können?", completion = "Die Insel gibt im Überfluss, Nahrung und Antworten gleichermaßen. Ihr müsst Euch nur umsehen, um zu finden, was Ihr sucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[33341] = { id = 33341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wegesrandschreine der Erhabenen", description = "Vor vielen Jahren war dies ein Pilgerort meines Volkes. Hier lauschte man den Worten der Erhabenen und meditierte viele Tage lang. Während der Meditationen fand jeder Ängste, Ärger, Verzweiflung, Zweifel und Gewalt, die seinen Geist plagten.\n\nVor allen lag ein Weg zur Erleuchtung. Jeder sah einen anderen Pfad, aber dieser begann für alle mit Weisheit.\n\nBereist die Insel, so wie sie, und entdeckt einen der verlorenen Wegesrandschreine der Erhabenen.", sourceObjective = "Findet einen aktiven zeitverlorenen Schrein und erbittet einen Segen von den Erhabenen.", progress = "Die Schreine öffnen sich Euch nicht immer. Gebt nicht auf, es ist alles eine Frage der Geduld.", completion = "Ihr habt die Macht und die Weisheit der Erhabenen erfahren. Lasst beides durch Euch fließen und bewahrt sie für immer in Eurem Herzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[33342] = { id = 33342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treibt die Flammen zurück", description = "Einst lebten die Pandaren in Harmonie mit den Yaungol von Ordos. Als die Insel plötzlich verschwand, blickten die Yaungol dem sicheren Tod ins Auge. In seiner Verzweiflung wandte sich der oberste Schamane an die Feuerlords um Hilfe. Und ihm wurde geantwortet.\n\nOrdos war sein Name. Heute ist er eine Kreatur des Zorns und der Gewalt. Obschon sein Volk gerettet wurde, brennt er doch endlos in geschmolzener Qual.\n\nHarmonie ist Vergangenheit. Die Ordosjünger streben danach, den Hof der Erhabenen einzunehmen und uns alle Ordos zu opfern. Schlagt sie zurück und stellt das Gleichgewicht wieder her.", sourceObjective = "Verdient Euch bei Shaohao einen wohlwollenden Ruf, indem Ihr auf der Zeitlosen Insel Yaungol vernichtet.", progress = "Mit den Ordosjüngern ist nicht zu spaßen. Unter dem Schutz ihres ewig brennenden Halbgottes Ordos haben sie auf dieser Insel überdauert.", completion = "Ihr habt viele Errungenschaften vorzuweisen und Eure Tapferkeit kann nicht angezweifelt werden. Für den Augenblick sind die Ordosjünger zurückgedrängt, Ihr solltet sie jedoch nicht unterschätzen. Um die Harmonie auf der Insel wiederherzustellen, müssen wir weiterhin wachsam bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[33343] = { id = 33343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Archiereus der Flamme", description = "Eure Bemühungen haben die Ordon zurückgetrieben und dem Hof der Erhabenen Frieden gebracht, aber dieser wird nicht von Bestand sein. Es ist Zeit, den großen Abgesandten von Ordos, den Archiereus der Flamme zum Schweigen zu bringen.\n\nSprecht mit Nebelwirker Ku und kauft eine Schriftrolle der Herausforderung. Dann reist zur Dreiwindterrasse im Norden. Sprecht eine Herausforderung am Herausforderungsstein aus. Das wird zweifellos die Aufmerksamkeit der Ordon erregen und den Archiereus aus dem Heiligtum von Ordos locken. Das ist Eure einzige Chance.", sourceObjective = "Beschwört und vernichtet den Archiereus der Flamme.", progress = "Die Gesandten von Ordos sind mächtig, Ihr solltet sie nicht unterschätzen.", completion = "Die Abgesandten von Ordos wurden zum Schweigen gebracht, wenigstens für eine Weile.\n\nIhr müsst wissen, dass Zorn, Gewalt und Hass niemals enden. Wo immer die Dunkelheit in einem Geist vorhanden ist, findet man diese Sha, die auf Euch warten. Sie nehmen viele Gestalten an: ein machthungriger Kriegsherr, ein nächtlicher Dolch im Rücken, ein junger Prinz, der den dunklen Weg einschlägt und sogar Euer Kampf gegen die Kräfte, die nicht mit den Euren im Einklang sind.\n\nLernt von diesen Gefühlen, damit Ihr Euch nicht in der Dunkelheit verliert.", sourceObjectiveStatus = "unverified-source-field" }
quests[33344] = { id = 33344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewaffnet und gefährlich", description = "Ligra wurde mit zusätzlichen Waffen hergeschickt, um die versklavten Frostwolforcs auszurüsten.\n\nSorgt für die Bewaffnung der Frostwölfe, damit sie die Sklavenhalter bekämpfen können.", sourceObjective = "Stattet 10 versklavte Frostwolforcs mit Waffen aus.", completion = "Die Oger scheinen in Aufruhr zu sein. Und viele meiner Leute sind jetzt frei.", sourceObjectiveStatus = "unverified-source-field" }
quests[33345] = { id = 33345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkelschamane wöchentlicher Versuch" }
quests[33346] = { id = 33346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "5.4 Test - RRP - Top Level Tracking Quest" }
quests[33347] = { id = 33347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "5.4 Test - RRP - Child Level Tracking Quest" }
quests[33348] = { id = 33348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Tom\" Bone Apart - Intro Tracking Quest" }
quests[33349] = { id = 33349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "STARTER QUEST - RED->PURPLE 15", description = "Hier gilt: Rennt durch den Bogen, erreicht die ROTE Markierung, dann die VIOLETTE Markierung und kehrt dann hierher zurück, bevor die Glocke 15-mal geschlagen hat. Viel Glück!", sourceObjective = "Rennt durch den Bogen, erreicht die rote Markierung, dann die violette Markierung und kehrt dann zum Lager der Eisenelfspiele zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[33350] = { id = 33350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redridge Group Trial" }
quests[33352] = { id = 33352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Chief killed" }
quests[33354] = { id = 33354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Niedergang der Höhlenmutter", description = "Dies ist der Pelz der monströsen Höhlenmutter der Dunkelmond-Insel.\n\nYebb Nabetand, Bestienmeister der Dunkelmond-Insel, wird erfreut sein zu erfahren, dass die geisterhafte Wölfin und ihre Jungen seine Menagerie nicht mehr terrorisieren werden… zumindest vorerst nicht. Bringt ihm den Pelz.", sourceObjective = "Bringt Mondfangs Pelz zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", progress = "Ist das, was ich denke, das es ist?", completion = "Endlich wurde diese bösartige Bestie erlegt! Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[33358] = { id = 33358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nudelzeit: Bonus", description = "Hallo, {name}. Ihr denkt also, <ein wahrlich meisterhafter Nudelkoch/eine wahrlich meisterhafte Nudelköchin> zu sein.\n\nDann zeigt uns doch mal, was Ihr draufhabt!", sourceObjective = "Reiht Euch für eine Schicht am Nudelstand von Halbhügel ein und schließt das Bonusziel ab.", progress = "Weiter so, {name}!", completion = "Großartige Arbeit, {name}! Alle sind immer voll freudiger Erwartung, wenn sie hören, dass Ihr Nudelsuppe macht. Die Leute kommen aus ganz Pandaria her, nur um sie zu probieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[33359] = { id = 33359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trefft uns beim Außenposten Sternenfall", description = "Der Erzmagier hat die potentielle Anwesenheit des Schattenrats im Tal aufgedeckt. Er hat mich darum gebeten, es Euch wissen zu lassen.\n\nKommt bitte so bald wie möglich zu uns zum Außenposten Sternenfall. Wir werden Euren Beistand benötigen, um sie zu beseitigen, Kommandant.", sourceObjective = "Sprecht mit Erzmagier Khadgar beim Außenposten Sternenfall.", completion = "Seid gegrüßt, {name}. Ihr kommt gerade rechtzeitig.\n\nWir haben den Schattenrat bis zu einem Dorf in der Nähe verfolgt. Ich vermute, dass sich Gul'dan bei ihnen aufhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[33360] = { id = 33360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "5.4 Raid - RRP - Boss 1 Legendary Quest" }
quests[33361] = { id = 33361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "5.4 Raid - RRP - Boss 2 Legendary Quest" }
